    wx = observation.get('grid_width', 0)
    wy = observation.get('grid_height', 0)
    pos = observation.get('self_position', [0, 0])
    x, y = pos[0], pos[1]
    resources = observation.get('resources', [])
    opponent_pos = observation.get('opponent_position', None)
    territory_info = observation.get('territory', None)
    settlers = observation.get('settlers', [])
    enemy_resources = observation.get('enemy_resources', [])

    if territory_info is None:
        territory_info = {}
    territory_map = territory_info.get('map', {})

    # Defensive extraction
    def get_owner(pos):
        return territory_map.get(f"{pos[0]},{pos[1]}", None)

    # Prioritize resource collection
    resource_targets = []
    for res in resources:
        resource_targets.append(res)
    if opponent_pos:
        resource_targets.append(opponent_pos)
    # Find unclaimed territory
    unclaimed = []
    for key, owner in territory_map.items():
        if owner != 'self':
            coords = list(map(int, key.split(',')))
            unclaimed.append(coords)
    if unclaimed:
        resource_targets.extend(unclaimed)
    # Avoid clustering with settlers
    for settler in settlers:
        if abs(settler[0] - x) + abs(settler[1] - y) < 3:
            resource_targets.append(settler)

    def distance(p):
        return abs(p[0] - x) + abs(p[1] - y)

    if resource_targets:
        target = min(resource_targets, key=distance)
        tx, ty = target
        dx = 0
        dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        # Prevent moving into own territory
        next_pos_owner = get_owner([x + dx, y + dy])
        if next_pos_owner == 'self':
            dx, dy = 0, 0
        return [dx, dy]
    return [0, 0]

